nextflow_process {

    name "Test Process GATK4_MUTECT2"
    script "../main.nf"
    process "GATK4_MUTECT2"

    tag "modules"
    tag "modules_nfcore"
    tag "gatk4"
    tag "gatk4/mutect2"
    config "./nextflow.config"

    test("human - bam - tumor_normal_pair") {
        when {
            params {
                module_args = "--normal-sample normal"
            }
            process {
            """
            input[0] = [
                [
                    id:'test',
                    normal_id:'normal',
                    tumor_id:'tumour'
                ],
                [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam', checkIfExists: true)
                ],
                [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test2.paired_end.recalibrated.sorted.bam.bai', checkIfExists: true)
                ],
                []
            ]
            input[1] = [
                [ id:'genome' ],
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true)
            ]
            input[2] = [
                [ id:'genome' ],
                [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta.fai', checkIfExists: true)],
                []
            ]
            input[3] = [
                [ id:'genome' ],
                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.dict', checkIfExists: true)
            ]
            input[4] = []
            input[5] = []
            input[6] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/germlineresources/gnomAD.r2.1.1.vcf.gz', checkIfExists: true)
            input[7] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/germlineresources/gnomAD.r2.1.1.vcf.gz.tbi', checkIfExists: true)
            input[8] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/germlineresources/mills_and_1000G.indels.hg38.vcf.gz', checkIfExists: true)
            input[9] = file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/germlineresources/mills_and_1000G.indels.hg38.vcf.gz.tbi', checkIfExists: true)
            """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    path(process.out.vcf.get(0).get(1)).vcf.variantsMD5,
                    process.out.tbi.collect { file(it[1]).getName() },
                    process.out.stats,
                    process.out.f1r2,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

